def fill_enclosed(grid, fill, background=None):
    """Every background-colored region not connected to the border is recolored fill."""
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    if background is None:
        background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False]*w for _ in range(h)]
    q = deque()
    for i in range(h):
        for j in (0, w-1):
            if grid[i][j] == background and not seen[i][j]:
                seen[i][j] = True; q.append((i, j))
    for j in range(w):
        for i in (0, h-1):
            if grid[i][j] == background and not seen[i][j]:
                seen[i][j] = True; q.append((i, j))
    while q:
        i, j = q.popleft()
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni, nj = i+di, j+dj
            if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == background and not seen[ni][nj]:
                seen[ni][nj] = True; q.append((ni, nj))
    return [[fill if grid[i][j] == background and not seen[i][j] else grid[i][j] for j in range(w)] for i in range(h)]

